-- Run supabase_setup.sql v3 first. This import is duplicate-safe.
on conflict (source_ref) where source_ref is not null do update set
 purchase_date=excluded.purchase_date, total_amount=excluded.total_amount;

-- Verification: expected 164 rows and Rs 27230 total.
select count(*) as imported_rows, sum(total_amount) as imported_total from public.store_entries where source_group='old_register';
